export const componentSource: Record<string, string> = {
  "Button": "\"use client\"\n\nimport { Button as BaseButton } from \"@base-ui/react/button\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\nconst buttonVariants = cva(\n  \"inline-flex min-h-10 items-center justify-center gap-2 rounded-[var(--radius-sm,6px)] px-4 text-sm font-medium transition-[color,background-color,border-color,transform] duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus)] data-[disabled]:pointer-events-none data-[disabled]:opacity-50 active:translate-y-px\",\n  {\n    variants: {\n      variant: {\n        primary: \"border border-[var(--ink)] bg-[var(--ink)] text-[var(--canvas)] hover:border-[var(--accent)] hover:bg-[var(--accent)]\",\n        secondary: \"border border-[var(--border)] bg-[var(--surface-inset)] text-[var(--ink)] hover:border-[var(--ink-secondary)]\",\n        outline: \"border border-[var(--border)] bg-[var(--surface)] text-[var(--ink)] hover:border-[var(--accent)] hover:text-[var(--accent)]\",\n        ghost: \"border border-transparent bg-transparent text-[var(--ink-secondary)] hover:bg-[var(--surface-inset)] hover:text-[var(--ink)]\",\n        danger: \"border border-[color-mix(in_oklab,var(--danger)_38%,var(--border))] bg-[color-mix(in_oklab,var(--danger)_10%,transparent)] text-[var(--danger)] hover:bg-[var(--danger)] hover:text-white\",\n      },\n      size: {\n        sm: \"min-h-8 px-3 text-xs\",\n        md: \"min-h-10 px-4 text-sm\",\n        lg: \"min-h-12 px-5 text-base\",\n        icon: \"size-10 min-h-10 px-0\",\n      },\n    },\n    defaultVariants: { variant: \"primary\", size: \"md\" },\n  },\n)\n\ntype ButtonProps = Omit<React.ComponentProps<typeof BaseButton>, \"className\"> &\n  VariantProps<typeof buttonVariants> & { className?: string }\n\nfunction Button({ className, variant, size, ...props }: ButtonProps) {\n  return (\n    <BaseButton\n      data-slot=\"button\"\n      className={cn(buttonVariants({ variant, size }), className)}\n      {...props}\n    />\n  )\n}\n\nexport { Button, buttonVariants, type ButtonProps }\n",
  "Field": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\nfunction Field({ className, ...props }: React.ComponentProps<\"div\">) {\n  return <div data-slot=\"field\" className={cn(\"grid gap-2\", className)} {...props} />\n}\n\nfunction FieldLabel({ className, ...props }: React.ComponentProps<\"label\">) {\n  return <label data-slot=\"field-label\" className={cn(\"text-sm font-medium text-[var(--ink)]\", className)} {...props} />\n}\n\nfunction FieldDescription({ className, ...props }: React.ComponentProps<\"p\">) {\n  return <p data-slot=\"field-description\" className={cn(\"m-0 text-xs leading-relaxed text-[var(--muted)]\", className)} {...props} />\n}\n\nfunction FieldError({ className, ...props }: React.ComponentProps<\"p\">) {\n  return <p data-slot=\"field-error\" role=\"alert\" className={cn(\"m-0 text-xs leading-relaxed text-[var(--danger)]\", className)} {...props} />\n}\n\nexport { Field, FieldDescription, FieldError, FieldLabel }\n",
  "Select": "\"use client\"\n\nimport { Select as BaseSelect } from \"@base-ui/react/select\"\nimport { Check, ChevronDown } from \"lucide-react\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\nconst Select = BaseSelect.Root\n\nfunction SelectTrigger({ className, children, ...props }: React.ComponentProps<typeof BaseSelect.Trigger>) {\n  return (\n    <BaseSelect.Trigger\n      data-slot=\"select-trigger\"\n      className={cn(\n        \"flex h-10 w-full items-center justify-between gap-3 rounded-[var(--radius-sm,6px)] border border-[var(--border)] bg-[var(--surface)] px-3 text-sm text-[var(--ink)] outline-none transition-[border-color,box-shadow] focus-visible:border-[var(--focus)] focus-visible:shadow-[0_0_0_3px_color-mix(in_oklab,var(--focus)_14%,transparent)] data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n      <BaseSelect.Icon><ChevronDown aria-hidden=\"true\" className=\"size-4 text-[var(--muted)]\" /></BaseSelect.Icon>\n    </BaseSelect.Trigger>\n  )\n}\n\nconst SelectValue = BaseSelect.Value\n\nfunction SelectContent({ className, children, ...props }: React.ComponentProps<typeof BaseSelect.Popup>) {\n  return (\n    <BaseSelect.Portal>\n      <BaseSelect.Positioner sideOffset={6} className=\"z-[100] outline-none\">\n        <BaseSelect.Popup\n          data-slot=\"select-content\"\n          className={cn(\n            \"min-w-[var(--anchor-width)] origin-[var(--transform-origin)] rounded-[var(--radius-md,10px)] border border-[var(--border)] bg-[var(--surface)] p-1 text-[var(--ink)] shadow-[0_16px_45px_color-mix(in_oklab,var(--ink)_12%,transparent)] outline-none transition-[transform,opacity] duration-150 data-[ending-style]:scale-[.98] data-[ending-style]:opacity-0 data-[starting-style]:scale-[.98] data-[starting-style]:opacity-0\",\n            className,\n          )}\n          {...props}\n        >\n          {children}\n        </BaseSelect.Popup>\n      </BaseSelect.Positioner>\n    </BaseSelect.Portal>\n  )\n}\n\nfunction SelectItem({ className, children, ...props }: React.ComponentProps<typeof BaseSelect.Item>) {\n  return (\n    <BaseSelect.Item\n      data-slot=\"select-item\"\n      className={cn(\n        \"grid min-h-9 cursor-default grid-cols-[1fr_18px] items-center gap-3 rounded-[var(--radius-xs,4px)] px-3 text-sm outline-none data-[highlighted]:bg-[var(--accent-soft)] data-[selected]:text-[var(--accent)] data-[disabled]:opacity-45\",\n        className,\n      )}\n      {...props}\n    >\n      <BaseSelect.ItemText>{children}</BaseSelect.ItemText>\n      <BaseSelect.ItemIndicator><Check aria-hidden=\"true\" className=\"size-4\" /></BaseSelect.ItemIndicator>\n    </BaseSelect.Item>\n  )\n}\n\nexport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue }\n",
  "Switch": "\"use client\"\n\nimport { Switch as BaseSwitch } from \"@base-ui/react/switch\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype SwitchProps = Omit<React.ComponentProps<typeof BaseSwitch.Root>, \"className\"> & { className?: string }\n\nfunction Switch({ className, ...props }: SwitchProps) {\n  return (\n    <BaseSwitch.Root\n      data-slot=\"switch\"\n      className={cn(\n        \"inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border border-[var(--border)] bg-[var(--surface-inset)] p-0.5 outline-none transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus)] data-[checked]:border-[var(--accent)] data-[checked]:bg-[var(--accent-soft)] data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50\",\n        className,\n      )}\n      {...props}\n    >\n      <BaseSwitch.Thumb className=\"block size-[18px] rounded-full bg-[var(--ink-secondary)] transition-transform duration-150 data-[checked]:translate-x-5 data-[checked]:bg-[var(--accent)]\" />\n    </BaseSwitch.Root>\n  )\n}\n\nexport { Switch, type SwitchProps }\n",
  "Dialog": "\"use client\"\n\nimport { Dialog as BaseDialog } from \"@base-ui/react/dialog\"\nimport { X } from \"lucide-react\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\nconst Dialog = BaseDialog.Root\nconst DialogTrigger = BaseDialog.Trigger\nconst DialogClose = BaseDialog.Close\n\nfunction DialogContent({ className, children, ...props }: React.ComponentProps<typeof BaseDialog.Popup>) {\n  return (\n    <BaseDialog.Portal>\n      <BaseDialog.Backdrop className=\"fixed inset-0 z-[90] bg-[color-mix(in_oklab,var(--ink)_38%,transparent)] transition-opacity duration-200 data-[ending-style]:opacity-0 data-[starting-style]:opacity-0\" />\n      <BaseDialog.Viewport className=\"fixed inset-0 z-[91] grid place-items-center overflow-y-auto p-4\">\n        <BaseDialog.Popup\n          data-slot=\"dialog-content\"\n          className={cn(\n            \"relative w-full max-w-lg rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] p-6 text-[var(--ink)] shadow-[0_28px_80px_color-mix(in_oklab,var(--ink)_22%,transparent)] outline-none transition-[transform,opacity] duration-200 data-[ending-style]:translate-y-2 data-[ending-style]:opacity-0 data-[starting-style]:translate-y-2 data-[starting-style]:opacity-0\",\n            className,\n          )}\n          {...props}\n        >\n          {children}\n          <BaseDialog.Close aria-label=\"Close dialog\" className=\"absolute right-4 top-4 grid size-8 place-items-center rounded-[var(--radius-sm,6px)] border border-transparent text-[var(--muted)] hover:border-[var(--border)] hover:text-[var(--ink)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--focus)]\">\n            <X aria-hidden=\"true\" className=\"size-4\" />\n          </BaseDialog.Close>\n        </BaseDialog.Popup>\n      </BaseDialog.Viewport>\n    </BaseDialog.Portal>\n  )\n}\n\nfunction DialogTitle({ className, ...props }: React.ComponentProps<typeof BaseDialog.Title>) {\n  return <BaseDialog.Title className={cn(\"m-0 pr-10 font-[family-name:var(--serif)] text-2xl font-medium tracking-tight\", className)} {...props} />\n}\n\nfunction DialogDescription({ className, ...props }: React.ComponentProps<typeof BaseDialog.Description>) {\n  return <BaseDialog.Description className={cn(\"mt-2 text-sm leading-relaxed text-[var(--ink-secondary)]\", className)} {...props} />\n}\n\nexport { Dialog, DialogClose, DialogContent, DialogDescription, DialogTitle, DialogTrigger }\n",
  "Command": "\"use client\"\n\nimport { Search } from \"lucide-react\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype CommandItem = { id: string; label: string; description?: string; keywords?: string[] }\n\ntype CommandProps = {\n  items: CommandItem[]\n  onSelect?: (item: CommandItem) => void\n  placeholder?: string\n  emptyText?: string\n  className?: string\n}\n\nfunction Command({ items, onSelect, placeholder = \"Type a command…\", emptyText = \"No commands found.\", className }: CommandProps) {\n  const [query, setQuery] = React.useState(\"\")\n  const [activeIndex, setActiveIndex] = React.useState(0)\n  const filtered = React.useMemo(() => {\n    const value = query.trim().toLowerCase()\n    if (!value) return items\n    return items.filter((item) => [item.label, item.description, ...(item.keywords ?? [])].filter(Boolean).join(\" \").toLowerCase().includes(value))\n  }, [items, query])\n\n  function select(item: CommandItem | undefined) {\n    if (item) onSelect?.(item)\n  }\n\n  return (\n    <div data-slot=\"command\" className={cn(\"overflow-hidden rounded-[var(--radius-md,10px)] border border-[var(--border)] bg-[var(--surface)]\", className)}>\n      <label className=\"flex h-11 items-center gap-3 border-b border-[var(--border-subtle)] px-3\">\n        <Search aria-hidden=\"true\" className=\"size-4 text-[var(--muted)]\" />\n        <span className=\"sr-only\">Command search</span>\n        <input\n          aria-controls=\"manner-command-list\"\n          aria-expanded=\"true\"\n          aria-activedescendant={filtered[activeIndex] ? `command-${filtered[activeIndex].id}` : undefined}\n          role=\"combobox\"\n          value={query}\n          onChange={(event) => { setQuery(event.target.value); setActiveIndex(0) }}\n          onKeyDown={(event) => {\n            if (event.key === \"ArrowDown\") { event.preventDefault(); setActiveIndex((index) => Math.min(index + 1, filtered.length - 1)) }\n            if (event.key === \"ArrowUp\") { event.preventDefault(); setActiveIndex((index) => Math.max(index - 1, 0)) }\n            if (event.key === \"Enter\") { event.preventDefault(); select(filtered[activeIndex]) }\n          }}\n          placeholder={placeholder}\n          className=\"h-full min-w-0 flex-1 bg-transparent text-sm text-[var(--ink)] outline-none placeholder:text-[var(--muted)]\"\n        />\n      </label>\n      <div id=\"manner-command-list\" role=\"listbox\" className=\"max-h-72 overflow-y-auto p-1\">\n        {filtered.length ? filtered.map((item, index) => (\n          <button\n            id={`command-${item.id}`}\n            key={item.id}\n            role=\"option\"\n            aria-selected={index === activeIndex}\n            className=\"grid w-full grid-cols-[1fr_auto] gap-4 rounded-[var(--radius-xs,4px)] px-3 py-2.5 text-left hover:bg-[var(--surface-inset)] aria-selected:bg-[var(--accent-soft)]\"\n            onMouseEnter={() => setActiveIndex(index)}\n            onClick={() => select(item)}\n          >\n            <span><strong className=\"block text-sm font-medium\">{item.label}</strong>{item.description && <small className=\"mt-0.5 block text-xs text-[var(--muted)]\">{item.description}</small>}</span>\n            <span aria-hidden=\"true\" className=\"text-[var(--accent)]\">↗</span>\n          </button>\n        )) : <p className=\"m-0 px-3 py-8 text-center text-sm text-[var(--muted)]\">{emptyText}</p>}\n      </div>\n    </div>\n  )\n}\n\nexport { Command, type CommandItem, type CommandProps }\n",
  "Surface": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype SurfaceProps = React.ComponentProps<\"section\"> & { tone?: \"default\" | \"inset\" | \"raised\" }\n\nfunction Surface({ className, tone = \"default\", ...props }: SurfaceProps) {\n  return (\n    <section\n      data-slot=\"surface\"\n      data-tone={tone}\n      className={cn(\n        \"rounded-[var(--radius-md,10px)] border p-5\",\n        tone === \"default\" && \"border-[var(--border)] bg-[var(--surface)]\",\n        tone === \"inset\" && \"border-[var(--border-subtle)] bg-[var(--surface-inset)]\",\n        tone === \"raised\" && \"border-[var(--border)] bg-[var(--surface)] shadow-[0_16px_45px_color-mix(in_oklab,var(--ink)_9%,transparent)]\",\n        className,\n      )}\n      {...props}\n    />\n  )\n}\n\nexport { Surface, type SurfaceProps }\n",
  "Section heading": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype SectionHeadingProps = Omit<React.ComponentProps<\"header\">, \"title\"> & {\n  eyebrow?: string\n  title: React.ReactNode\n  description?: React.ReactNode\n  action?: React.ReactNode\n}\n\nfunction SectionHeading({ eyebrow, title, description, action, className, ...props }: SectionHeadingProps) {\n  return (\n    <header data-slot=\"section-heading\" className={cn(\"grid gap-5 border-l-2 border-[var(--accent)] pl-5 sm:grid-cols-[1fr_auto]\", className)} {...props}>\n      <div>\n        {eyebrow && <p className=\"m-0 font-mono text-[.68rem] uppercase tracking-[.13em] text-[var(--accent)]\">{eyebrow}</p>}\n        <h2 className=\"my-2 font-[family-name:var(--serif)] text-4xl font-medium leading-[.98] tracking-[-.035em] text-[var(--ink)]\">{title}</h2>\n        {description && <p className=\"m-0 max-w-[62ch] text-sm leading-relaxed text-[var(--ink-secondary)]\">{description}</p>}\n      </div>\n      {action && <div>{action}</div>}\n    </header>\n  )\n}\n\nexport { SectionHeading, type SectionHeadingProps }\n",
  "Note": "import { Sparkles } from \"lucide-react\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype NoteProps = React.ComponentProps<\"aside\"> & { title?: React.ReactNode }\n\nfunction Note({ title, children, className, ...props }: NoteProps) {\n  return (\n    <aside data-slot=\"note\" className={cn(\"grid grid-cols-[24px_1fr] gap-4 rounded-[var(--radius-sm,6px)] border border-[var(--border)] border-l-[3px] border-l-[var(--accent)] bg-[var(--surface)] p-5\", className)} {...props}>\n      <Sparkles aria-hidden=\"true\" className=\"mt-0.5 size-4 text-[var(--accent)]\" />\n      <div>{title && <strong className=\"font-[family-name:var(--serif)] text-lg font-medium\">{title}</strong>}<div className=\"mt-1.5 text-sm leading-relaxed text-[var(--ink-secondary)]\">{children}</div></div>\n    </aside>\n  )\n}\n\nexport { Note, type NoteProps }\n",
  "Quote": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype QuoteProps = React.ComponentProps<\"figure\"> & { cite: React.ReactNode }\n\nfunction Quote({ children, cite, className, ...props }: QuoteProps) {\n  return (\n    <figure data-slot=\"quote\" className={cn(\"m-0 border-y border-[var(--border)] py-8\", className)} {...props}>\n      <blockquote className=\"m-0 font-[family-name:var(--serif)] text-3xl leading-tight tracking-[-.025em] text-[var(--ink)]\">“{children}”</blockquote>\n      <figcaption className=\"mt-5 font-mono text-xs text-[var(--muted)]\">— {cite}</figcaption>\n    </figure>\n  )\n}\n\nexport { Quote, type QuoteProps }\n",
  "Timeline": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype TimelineEntry = { date: React.ReactNode; title: React.ReactNode; description?: React.ReactNode }\ntype TimelineProps = React.ComponentProps<\"ol\"> & { items: TimelineEntry[] }\n\nfunction Timeline({ items, className, ...props }: TimelineProps) {\n  return (\n    <ol data-slot=\"timeline\" className={cn(\"m-0 list-none p-0\", className)} {...props}>\n      {items.map((item, index) => (\n        <li key={index} className=\"grid grid-cols-[34px_1fr] gap-4 pb-6 last:pb-0\">\n          <span className=\"grid size-8 place-items-center rounded-full border border-[var(--border)] font-mono text-xs text-[var(--accent)]\">{String(index + 1).padStart(2, \"0\")}</span>\n          <div className=\"border-b border-[var(--border-subtle)] pb-5 last:border-0\"><time className=\"font-mono text-[.68rem] uppercase tracking-wider text-[var(--muted)]\">{item.date}</time><h3 className=\"my-1 font-[family-name:var(--serif)] text-lg font-medium\">{item.title}</h3>{item.description && <p className=\"m-0 text-sm leading-relaxed text-[var(--ink-secondary)]\">{item.description}</p>}</div>\n        </li>\n      ))}\n    </ol>\n  )\n}\n\nexport { Timeline, type TimelineEntry, type TimelineProps }\n",
  "Metadata": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype MetadataItem = { label: React.ReactNode; value: React.ReactNode }\ntype MetadataProps = React.ComponentProps<\"dl\"> & { items: MetadataItem[] }\n\nfunction Metadata({ items, className, ...props }: MetadataProps) {\n  return (\n    <dl data-slot=\"metadata\" className={cn(\"m-0 divide-y divide-[var(--border-subtle)] rounded-[var(--radius-sm,6px)] border border-[var(--border)] bg-[var(--surface)]\", className)} {...props}>\n      {items.map((item, index) => <div key={index} className=\"grid grid-cols-[1fr_1.4fr] gap-4 px-4 py-3\"><dt className=\"font-mono text-xs text-[var(--muted)]\">{item.label}</dt><dd className=\"m-0 text-sm text-[var(--ink)]\">{item.value}</dd></div>)}\n    </dl>\n  )\n}\n\nexport { Metadata, type MetadataItem, type MetadataProps }\n",
  "Message": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype MessageProps = React.ComponentProps<\"article\"> & {\n  from: \"user\" | \"assistant\"\n  label?: string\n  actions?: React.ReactNode\n}\n\nfunction Message({ from, label, actions, children, className, ...props }: MessageProps) {\n  return (\n    <article data-slot=\"message\" data-from={from} className={cn(\"group grid max-w-[68ch] gap-2 data-[from=user]:ml-auto data-[from=user]:max-w-[78%] data-[from=user]:rounded-[var(--radius-md,10px)] data-[from=user]:bg-[var(--accent-soft)] data-[from=user]:p-4\", className)} {...props}>\n      <span className=\"font-mono text-[.66rem] uppercase tracking-wider text-[var(--muted)]\">{label ?? (from === \"user\" ? \"You\" : \"Manner\")}</span>\n      <div className=\"text-sm leading-relaxed text-[var(--ink)]\">{children}</div>\n      {actions && <footer className=\"flex gap-3 text-xs text-[var(--muted)] opacity-75 transition-opacity group-hover:opacity-100 group-focus-within:opacity-100\">{actions}</footer>}\n    </article>\n  )\n}\n\nexport { Message, type MessageProps }\n",
  "Composer": "\"use client\"\n\nimport { ArrowUp, Plus } from \"lucide-react\"\nimport * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\nimport { Button } from \"@/registry/manner/ui/button\"\nimport { Textarea } from \"@/registry/manner/ui/textarea\"\n\ntype ComposerProps = Omit<React.ComponentProps<\"form\">, \"onSubmit\"> & {\n  value: string\n  onValueChange: (value: string) => void\n  onSubmit: (value: string) => void\n  placeholder?: string\n  disabled?: boolean\n  contextAction?: React.ReactNode\n}\n\nfunction Composer({ value, onValueChange, onSubmit, placeholder = \"Ask Manner…\", disabled, contextAction, className, ...props }: ComposerProps) {\n  return (\n    <form\n      data-slot=\"composer\"\n      className={cn(\"rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] p-3 shadow-[0_16px_45px_color-mix(in_oklab,var(--ink)_8%,transparent)]\", className)}\n      onSubmit={(event) => { event.preventDefault(); if (value.trim()) onSubmit(value.trim()) }}\n      {...props}\n    >\n      <Textarea\n        aria-label=\"Message\"\n        value={value}\n        onChange={(event) => onValueChange(event.target.value)}\n        onKeyDown={(event) => { if ((event.metaKey || event.ctrlKey) && event.key === \"Enter\") event.currentTarget.form?.requestSubmit() }}\n        placeholder={placeholder}\n        disabled={disabled}\n        className=\"min-h-24 resize-none border-0 bg-transparent px-1 shadow-none focus-visible:shadow-none\"\n      />\n      <footer className=\"mt-2 flex items-center justify-between gap-3\">\n        {contextAction ?? <button type=\"button\" className=\"inline-flex items-center gap-1.5 text-xs text-[var(--muted)] hover:text-[var(--ink)]\"><Plus aria-hidden=\"true\" className=\"size-3.5\" /> Add context</button>}\n        <div className=\"flex items-center gap-2\"><kbd className=\"hidden font-mono text-[.65rem] text-[var(--muted)] sm:inline\">⌘ ↵</kbd><Button type=\"submit\" size=\"icon\" disabled={disabled || !value.trim()} aria-label=\"Send message\"><ArrowUp aria-hidden=\"true\" className=\"size-4\" /></Button></div>\n      </footer>\n    </form>\n  )\n}\n\nexport { Composer, type ComposerProps }\n",
  "Reasoning": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype ReasoningProps = React.ComponentProps<\"details\"> & { title?: React.ReactNode; summary?: React.ReactNode }\n\nfunction Reasoning({ title = \"How this was decided\", summary, children, className, ...props }: ReasoningProps) {\n  return (\n    <details data-slot=\"reasoning\" className={cn(\"group rounded-[var(--radius-sm,6px)] border border-[var(--border)] bg-[var(--surface)]\", className)} {...props}>\n      <summary className=\"flex cursor-pointer list-none items-center gap-3 p-4 text-sm font-medium focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus)]\"><span className=\"size-2 rounded-full bg-[var(--accent)] shadow-[0_0_0_4px_var(--accent-soft)]\" />{title}{summary && <small className=\"ml-auto text-xs font-normal text-[var(--muted)]\">{summary}</small>}</summary>\n      <div className=\"border-t border-[var(--border-subtle)] px-5 py-4 text-sm leading-relaxed text-[var(--ink-secondary)]\">{children}</div>\n    </details>\n  )\n}\n\nexport { Reasoning, type ReasoningProps }\n",
  "Tool call": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype ToolCallProps = React.ComponentProps<\"section\"> & { name: string; status: \"running\" | \"complete\" | \"error\"; duration?: string }\n\nfunction ToolCall({ name, status, duration, children, className, ...props }: ToolCallProps) {\n  return (\n    <section data-slot=\"tool-call\" data-status={status} className={cn(\"overflow-hidden rounded-[var(--radius-sm,6px)] border border-[var(--border)] bg-[var(--surface)]\", className)} {...props}>\n      <header className=\"flex items-center justify-between gap-4 p-4\"><div><code className=\"font-mono text-sm text-[var(--ink)]\">{name}</code>{duration && <small className=\"ml-2 text-[var(--muted)]\">{duration}</small>}</div><span className=\"font-mono text-[.66rem] uppercase tracking-wider text-[var(--accent)] data-[status=error]:text-[var(--danger)]\" data-status={status}>{status}</span></header>\n      <div className=\"border-t border-[var(--border-subtle)] bg-[var(--surface-inset)] p-4 text-sm leading-relaxed text-[var(--ink-secondary)]\">{children}</div>\n    </section>\n  )\n}\n\nexport { ToolCall, type ToolCallProps }\n",
  "Sources": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype SourceItem = { title: string; domain: string; href: string }\ntype SourcesProps = React.ComponentProps<\"ol\"> & { items: SourceItem[] }\n\nfunction Sources({ items, className, ...props }: SourcesProps) {\n  return (\n    <ol data-slot=\"sources\" className={cn(\"m-0 list-none divide-y divide-[var(--border-subtle)] p-0\", className)} {...props}>\n      {items.map((item, index) => <li key={item.href}><a href={item.href} target=\"_blank\" rel=\"noreferrer\" className=\"grid grid-cols-[28px_1fr_auto] items-center gap-3 py-4 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--focus)]\"><span className=\"font-mono text-xs text-[var(--accent)]\">{String(index + 1).padStart(2, \"0\")}</span><span><strong className=\"block font-[family-name:var(--serif)] text-base font-medium\">{item.title}</strong><small className=\"text-xs text-[var(--muted)]\">{item.domain}</small></span><span aria-hidden=\"true\" className=\"text-[var(--accent)]\">↗</span></a></li>)}\n    </ol>\n  )\n}\n\nexport { Sources, type SourceItem, type SourcesProps }\n",
  "Artifact": "import * as React from \"react\"\n\nimport { cn } from \"@/lib/cn\"\n\ntype ArtifactProps = React.ComponentProps<\"section\"> & { title: React.ReactNode; type: React.ReactNode; actions?: React.ReactNode }\n\nfunction Artifact({ title, type, actions, children, className, ...props }: ArtifactProps) {\n  return (\n    <section data-slot=\"artifact\" className={cn(\"overflow-hidden rounded-[var(--radius-md,10px)] border border-[var(--border)] bg-[var(--surface)] shadow-[0_16px_45px_color-mix(in_oklab,var(--ink)_8%,transparent)]\", className)} {...props}>\n      <header className=\"flex min-h-12 items-center justify-between gap-4 border-b border-[var(--border)] px-4\"><div><strong className=\"text-sm font-medium\">{title}</strong><span className=\"ml-2 font-mono text-[.65rem] uppercase tracking-wider text-[var(--accent)]\">{type}</span></div>{actions}</header>\n      <div className=\"min-h-48 bg-[var(--surface-inset)] p-5 font-mono text-sm leading-relaxed text-[var(--ink-secondary)]\">{children}</div>\n    </section>\n  )\n}\n\nexport { Artifact, type ArtifactProps }\n"
}

export const blockSource: Record<string, string> = {
  "login-01": "\"use client\"\n\nimport * as React from \"react\"\n\nimport { Button } from \"@/registry/manner/ui/button\"\nimport { Field, FieldDescription, FieldLabel } from \"@/registry/manner/ui/field\"\nimport { Input } from \"@/registry/manner/ui/input\"\n\nfunction LoginBlock() {\n  const [complete, setComplete] = React.useState(false)\n\n  return (\n    <main className=\"grid min-h-[560px] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] lg:grid-cols-[1.08fr_.92fr]\">\n      <section className=\"flex flex-col justify-between bg-[var(--ink)] p-8 text-[var(--canvas)] sm:p-12\"><div><span className=\"grid size-11 place-items-center rounded-full border border-[color-mix(in_oklab,var(--canvas)_35%,transparent)] font-[family-name:var(--serif)] text-xl\">M</span><p className=\"mt-12 font-mono text-[.68rem] uppercase tracking-[.14em] text-[var(--accent)]\">The editorial workspace</p><h1 className=\"mt-4 font-[family-name:var(--serif)] text-5xl font-medium leading-[.92] tracking-[-.045em]\">Make room for<br/><i className=\"font-normal text-[var(--accent)]\">better thinking.</i></h1></div><blockquote className=\"m-0 max-w-sm border-l border-[var(--accent)] pl-4 font-[family-name:var(--serif)] text-lg italic text-[color-mix(in_oklab,var(--canvas)_78%,transparent)]\">“The interface recedes. The work remains.”</blockquote></section>\n      <form className=\"flex flex-col justify-center gap-5 p-8 sm:p-12\" onSubmit={(event) => { event.preventDefault(); setComplete(true) }}><div><p className=\"m-0 font-mono text-[.68rem] uppercase tracking-[.13em] text-[var(--accent)]\">Welcome back</p><h2 className=\"my-2 font-[family-name:var(--serif)] text-3xl font-medium\">{complete ? \"Workspace ready.\" : \"Sign in to Manner\"}</h2><p className=\"m-0 text-sm leading-relaxed text-[var(--ink-secondary)]\">{complete ? \"The authenticated state is represented locally in this example.\" : \"Continue to your notes, decisions, and active work.\"}</p></div>{complete ? <Button type=\"button\" variant=\"outline\" onClick={() => setComplete(false)}>Reset example</Button> : <><Field><FieldLabel htmlFor=\"manner-login-email\">Email</FieldLabel><Input id=\"manner-login-email\" name=\"email\" type=\"email\" autoComplete=\"email\" required defaultValue=\"yuda@example.com\"/></Field><Field><FieldLabel htmlFor=\"manner-login-password\">Password</FieldLabel><Input id=\"manner-login-password\" name=\"password\" type=\"password\" autoComplete=\"current-password\" required defaultValue=\"manner-demo\"/><FieldDescription>Example credentials stay in your browser.</FieldDescription></Field><Button type=\"submit\">Continue →</Button></>}</form>\n    </main>\n  )\n}\n\nexport { LoginBlock }\n",
  "sidebar-01": "\"use client\"\n\nimport * as React from \"react\"\n\nimport { Button } from \"@/registry/manner/ui/button\"\n\nconst navigation = [\"Overview\", \"Work\", \"Library\", \"Review\"]\n\nfunction SidebarBlock() {\n  const [collapsed, setCollapsed] = React.useState(false)\n  const [active, setActive] = React.useState(\"Overview\")\n  return (\n    <div className={collapsed ? \"grid min-h-[560px] grid-cols-[72px_1fr] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)]\" : \"grid min-h-[560px] grid-cols-[220px_1fr] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)]\"}>\n      <aside className=\"flex min-w-0 flex-col border-r border-[var(--border)] bg-[var(--surface-inset)] p-3\"><header className=\"flex h-10 items-center gap-3\"><span className=\"grid size-8 shrink-0 place-items-center rounded-[var(--radius-sm,6px)] bg-[var(--ink)] font-[family-name:var(--serif)] text-[var(--canvas)]\">M</span>{!collapsed && <strong className=\"truncate font-[family-name:var(--serif)]\">Manner Studio</strong>}<button className=\"ml-auto text-[var(--muted)]\" aria-label=\"Toggle sidebar\" onClick={() => setCollapsed(!collapsed)}>↔</button></header><nav aria-label=\"Workspace\" className=\"mt-8 grid gap-1\">{navigation.map((item, index) => <button key={item} className=\"grid h-10 grid-cols-[28px_1fr] items-center rounded-[var(--radius-sm,6px)] px-2 text-left text-sm text-[var(--ink-secondary)] hover:bg-[var(--surface)] aria-[current=page]:bg-[var(--accent-soft)] aria-[current=page]:text-[var(--ink)]\" aria-current={active === item ? \"page\" : undefined} onClick={() => setActive(item)}><span className=\"text-[var(--accent)]\">{[\"○\", \"⌁\", \"◇\", \"↗\"][index]}</span>{!collapsed && <span>{item}</span>}</button>)}</nav><footer className=\"mt-auto border-t border-[var(--border-subtle)] pt-3 text-xs text-[var(--muted)]\">{collapsed ? \"MY\" : \"Muchamad Yuda\"}</footer></aside>\n      <section className=\"min-w-0 p-6 sm:p-8\"><header className=\"flex items-center justify-between gap-4 text-sm text-[var(--muted)]\"><span>Workspace / {active}</span><Button size=\"sm\">New note ＋</Button></header><h2 className=\"mt-10 font-[family-name:var(--serif)] text-4xl font-medium tracking-tight\">Good afternoon.</h2><div className=\"mt-8 grid border-l border-t border-[var(--border)] sm:grid-cols-3\">{[[\"Open threads\", \"12\", \"+3 this week\"], [\"Reading time\", \"4.2h\", \"Across 8 notes\"], [\"Decisions\", \"07\", \"2 need review\"]].map(([label, value, detail]) => <article key={label} className=\"flex min-h-32 flex-col border-b border-r border-[var(--border)] p-4\"><span className=\"font-mono text-[.65rem] uppercase tracking-wider text-[var(--muted)]\">{label}</span><strong className=\"mt-auto font-[family-name:var(--serif)] text-3xl font-medium\">{value}</strong><small className=\"text-[var(--accent)]\">{detail}</small></article>)}</div></section>\n    </div>\n  )\n}\n\nexport { SidebarBlock }\n",
  "settings-01": "\"use client\"\n\nimport * as React from \"react\"\n\nimport { Button } from \"@/registry/manner/ui/button\"\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from \"@/registry/manner/ui/select\"\nimport { Switch } from \"@/registry/manner/ui/switch\"\n\nfunction SettingsBlock() {\n  const [motion, setMotion] = React.useState(true)\n  const [saved, setSaved] = React.useState(false)\n  return (\n    <div className=\"grid min-h-[520px] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] md:grid-cols-[210px_1fr]\">\n      <aside className=\"border-b border-[var(--border)] bg-[var(--surface-inset)] p-4 md:border-b-0 md:border-r\"><p className=\"font-mono text-[.68rem] uppercase tracking-wider text-[var(--muted)]\">Settings</p><nav className=\"flex gap-1 overflow-x-auto md:grid\">{[\"Profile\", \"Appearance\", \"Writing\", \"Integrations\", \"Advanced\"].map((item) => <button key={item} className=\"whitespace-nowrap border-l-2 border-transparent px-3 py-2 text-left text-sm text-[var(--ink-secondary)] aria-[current=page]:border-[var(--accent)] aria-[current=page]:bg-[var(--accent-soft)] aria-[current=page]:text-[var(--ink)]\" aria-current={item === \"Writing\" ? \"page\" : undefined}>{item}</button>)}</nav></aside>\n      <main className=\"w-full max-w-2xl p-6 sm:p-10\"><p className=\"font-mono text-[.68rem] uppercase tracking-wider text-[var(--accent)]\">Writing & motion</p><h2 className=\"my-2 font-[family-name:var(--serif)] text-3xl font-medium\">Writing preferences</h2><p className=\"text-sm leading-relaxed text-[var(--ink-secondary)]\">Choose how the workspace responds while you think and write.</p><div className=\"mt-8 divide-y divide-[var(--border)] border-y border-[var(--border)]\"><label className=\"flex items-center justify-between gap-6 py-5\"><span><strong className=\"block text-sm\">Reduced motion</strong><small className=\"mt-1 block text-xs text-[var(--muted)]\">Simplify transitions and panel movement.</small></span><Switch checked={motion} onCheckedChange={setMotion} aria-label=\"Reduced motion\" /></label><div className=\"grid gap-2 py-5\"><span className=\"text-sm font-medium\">Writing tone</span><Select defaultValue=\"editorial\"><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value=\"editorial\">Editorial warm</SelectItem><SelectItem value=\"neutral\">Quiet neutral</SelectItem><SelectItem value=\"dense\">Dense product</SelectItem></SelectContent></Select></div></div><Button className=\"mt-6\" onClick={() => setSaved(true)}>{saved ? \"Saved ✓\" : \"Save preferences\"}</Button></main>\n    </div>\n  )\n}\n\nexport { SettingsBlock }\n",
  "reader-01": "import { Note } from \"@/registry/manner/editorial/note\"\n\nfunction ReaderBlock() {\n  return (\n    <div className=\"grid min-h-[560px] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] lg:grid-cols-[180px_1fr_230px]\">\n      <aside className=\"hidden border-r border-[var(--border)] bg-[var(--surface-inset)] p-5 lg:flex lg:flex-col\"><p className=\"font-mono text-[.65rem] uppercase tracking-wider text-[var(--muted)]\">On this page</p>{[\"A system, not a style\", \"Visual authority\", \"Semantic tokens\", \"Agent constraints\"].map((item, index) => <a key={item} href={`#reader-${index}`} className={index === 0 ? \"py-2 text-sm text-[var(--accent)]\" : \"py-2 text-sm text-[var(--muted)]\"}>{item}</a>)}<span className=\"mt-auto font-mono text-[.65rem] text-[var(--accent)]\">42% read</span></aside><article className=\"mx-auto max-w-[68ch] p-8 sm:p-12\"><p className=\"font-mono text-[.65rem] uppercase tracking-wider text-[var(--accent)]\">Design systems / 08 min</p><h1 id=\"reader-0\" className=\"my-5 font-[family-name:var(--serif)] text-5xl font-medium leading-[.92] tracking-[-.045em]\">A system,<br/><i className=\"font-normal text-[var(--accent)]\">not a style.</i></h1><p className=\"font-[family-name:var(--serif)] text-xl leading-relaxed\">A useful interface system does not merely prescribe what things look like. It explains why they exist and how they behave under pressure.</p><p className=\"text-base leading-7 text-[var(--ink-secondary)]\">Color and type are only the visible edge. The deeper system connects intent, component anatomy, application patterns, agent instructions, and tests.</p><blockquote className=\"my-8 border-l-2 border-[var(--accent)] pl-5 font-[family-name:var(--serif)] text-xl italic\">Portable taste requires rules that survive implementation.</blockquote></article><aside className=\"hidden border-l border-[var(--border)] bg-[var(--surface-inset)] p-5 lg:block\"><Note title=\"Structure precedes decoration.\">Every container should explain a relationship.</Note></aside>\n    </div>\n  )\n}\n\nexport { ReaderBlock }\n",
  "ai-workspace-01": "\"use client\"\n\nimport * as React from \"react\"\n\nimport { Artifact } from \"@/registry/manner/ai/artifact\"\nimport { Composer } from \"@/registry/manner/ai/composer\"\nimport { Message } from \"@/registry/manner/ai/message\"\n\nfunction AIWorkspaceBlock() {\n  const [value, setValue] = React.useState(\"Turn that into an implementation checklist\")\n  const [messages, setMessages] = React.useState<string[]>([])\n  return (\n    <div className=\"grid min-h-[570px] overflow-hidden rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] lg:grid-cols-[1.08fr_.92fr]\">\n      <main className=\"grid min-h-0 grid-rows-[auto_1fr_auto]\"><header className=\"flex h-14 items-center gap-3 border-b border-[var(--border)] px-4\"><span className=\"grid size-8 place-items-center rounded-full bg-[var(--ink)] font-[family-name:var(--serif)] text-[var(--canvas)]\">M</span><div><strong className=\"block text-sm\">Design review</strong><small className=\"text-xs text-[var(--muted)]\">3 sources attached</small></div></header><div className=\"flex flex-col gap-6 overflow-y-auto p-6\"><Message from=\"user\">How should this dashboard adapt on mobile?</Message><Message from=\"assistant\" actions={<><button>Copy</button><button>Useful</button></>}>Keep one primary panel at a time. Replace the persistent sidebar with a sheet, and move the artifact into a full-screen drawer.</Message>{messages.map((message) => <Message from=\"user\" key={message}>{message}</Message>)}</div><Composer value={value} onValueChange={setValue} onSubmit={(message) => { setMessages((current) => [...current, message]); setValue(\"\") }} className=\"m-4\" /></main><aside className=\"hidden bg-[var(--ink)] p-5 text-[var(--canvas)] lg:block\"><Artifact title=\"mobile-plan.md\" type=\"Markdown\" className=\"border-[color-mix(in_oklab,var(--canvas)_18%,transparent)] bg-transparent text-[var(--canvas)]\"><pre className=\"m-0 whitespace-pre-wrap\">{`# Mobile adaptation\\n\\n- one active panel\\n- sidebar → sheet\\n- artifact → drawer\\n- keep actions visible`}</pre></Artifact></aside>\n    </div>\n  )\n}\n\nexport { AIWorkspaceBlock }\n",
  "leaderboard-01": "import { Metadata } from \"@/registry/manner/editorial/metadata\"\n\nconst models = [\n  [\"01\", \"Nusantara 3\", \"1284\", \"68%\", \"↗ 24\"],\n  [\"02\", \"Gemini Flash\", \"1249\", \"64%\", \"↗ 11\"],\n  [\"03\", \"GPT Luna\", \"1218\", \"61%\", \"→ 0\"],\n  [\"04\", \"Qwen Fast\", \"1192\", \"58%\", \"↘ 7\"],\n]\n\nfunction LeaderboardBlock() {\n  return (\n    <section className=\"min-h-[520px] rounded-[var(--radius-lg,14px)] border border-[var(--border)] bg-[var(--surface)] p-6 sm:p-8\"><header className=\"flex items-start justify-between gap-5\"><div><p className=\"m-0 font-mono text-[.65rem] uppercase tracking-wider text-[var(--accent)]\">Arena Indo / July</p><h2 className=\"my-2 font-[family-name:var(--serif)] text-3xl font-medium\">Model leaderboard</h2></div><a href=\"#methodology\" className=\"text-sm text-[var(--ink-secondary)]\">Methodology ↗</a></header><Metadata className=\"my-7 grid divide-y-0 sm:grid-cols-3\" items={[{ label: \"Valid votes\", value: \"18,420\" }, { label: \"Decisive\", value: \"62%\" }, { label: \"Models\", value: \"24\" }]} /><div className=\"overflow-x-auto\"><table className=\"w-full min-w-[620px] border-collapse text-left\"><thead><tr className=\"border-b border-[var(--border)] font-mono text-[.65rem] uppercase tracking-wider text-[var(--muted)]\"><th className=\"py-3 font-normal\">Rank / model</th><th className=\"py-3 font-normal\">ELO</th><th className=\"py-3 font-normal\">Win rate</th><th className=\"py-3 font-normal\">Trend</th></tr></thead><tbody>{models.map((row) => <tr key={row[1]} className=\"border-b border-[var(--border-subtle)] text-sm\"><td className=\"py-4\"><span className=\"mr-5 font-mono text-xs text-[var(--accent)]\">{row[0]}</span><strong>{row[1]}</strong></td><td>{row[2]}</td><td>{row[3]}</td><td className=\"text-[var(--accent)]\">{row[4]}</td></tr>)}</tbody></table></div></section>\n  )\n}\n\nexport { LeaderboardBlock }\n"
}

export const designSource = "# Manner Interface Rules\n\nManner is a warm, editorial interface system for thoughtful software.\nIt is independent and is not affiliated with Anthropic or Claude.\n\n## Product feeling\n\nInterfaces should feel literate, calm, curious, competent, warm, and slightly unconventional. They should never feel corporate-luxury, faux-vintage, overly cute, or generically AI-generated.\n\n## Non-negotiable rules\n\n- Use semantic design tokens. Do not add arbitrary color values inside components.\n- Search existing components and blocks before creating a new primitive.\n- Use visible surfaces only when grouping requires a container.\n- Do not wrap every section, statistic, or list item in a card.\n- Use serif typography only for major titles, quotes, selected numbers, and editorial emphasis.\n- Use sans-serif typography for controls, forms, tables, and dense reading.\n- Use monospace for metadata, code, keyboard hints, timestamps, and system state.\n- Use thin borders and tonal contrast before shadows.\n- Keep control radii small to medium. Pills are reserved for status, tags, and compact filters.\n- Motion must explain state, continuity, hierarchy, or origin.\n- Every interaction needs visible keyboard focus and an accessible name.\n- Design mobile layouts intentionally. Do not merely shrink desktop grids.\n- Respect `prefers-reduced-motion`.\n\n## Semantic tokens\n\nUse `canvas`, `surface`, `surface-raised`, `surface-inset`, `ink`, `ink-secondary`, `ink-muted`, `accent`, `accent-soft`, `border-subtle`, `border`, `border-strong`, `focus`, `success`, `warning`, `danger`, and `info` instead of component-specific colors.\n\n## Typography\n\n- Display: Fraunces Variable, approximately weight 420.\n- Interface and body: Geist or Inter Variable.\n- Code and metadata: IBM Plex Mono.\n- Keep long-form body measure between 58 and 72 characters.\n- Use line-height 1.55–1.75 for prose.\n- Never use serif for tiny labels, dense tables, or code-adjacent UI.\n\n## Shape and elevation\n\n- xs radius: 4px\n- sm radius: 6px\n- md radius: 10px\n- lg radius: 14px\n- xl radius: 20px, only for major canvases\n\nMost content grouping uses no shadow. Menus may use lift-1. Dialogs may use lift-2. Do not place giant blurred shadows behind normal cards.\n\n## Motion vocabulary\n\n- `enter-soft`\n- `exit-soft`\n- `reveal-line`\n- `shift-active`\n- `expand-panel`\n- `swap-content`\n- `press-control`\n\nMicro-interactions use 100–160ms. Menus and overlays use 140–220ms. Panels and layout changes use 180–300ms. Avoid bounce and decorative zoom by default.\n\n## Responsive behavior\n\nValidate at 360, 390, 768, 1024, and 1440 pixels. Sidebars become sheets, tabs, or compact selectors. Multi-panel AI interfaces show one primary panel at a time. Keep essential actions available without hover. Preserve readable measure.\n\n## Accessibility\n\nTarget WCAG 2.2 AA with full keyboard operation, visible focus, accessible names, correct field relationships, non-color state indicators, logical focus order, dialog focus restoration, reduced motion, and 400% reflow.\n\n## Avoid\n\n- arbitrary colors inside components\n- generic gradients and gradient text\n- glassmorphism for ordinary surfaces\n- giant centered hero followed by three generic cards\n- nested card inside card inside card\n- every control rendered as a pill\n- decorative motion that delays interaction\n- low-contrast beige-on-beige text\n- fixed-height content that clips user text or localization\n- icon-only actions without labels\n\n## Agent workflow\n\n1. Inspect the existing application structure, `components.json`, and tokens.\n2. Reuse Manner components before creating new primitives. Add missing source with `pnpm dlx shadcn@latest add @manner/<name>`.\n3. Choose a composition based on the user task, not visual novelty.\n4. Implement loading, empty, error, disabled, and overflow states where applicable.\n5. Verify keyboard use, visible focus, reduced motion, and mobile transformation.\n6. Explain any intentional exception to these rules.\n7. Update documentation and tests when component behavior changes.\n\nInstall the rules and a component with:\n\n```sh\npnpm dlx shadcn@latest registry add @manner=https://ui.myudak.com/r/{name}.json\npnpm dlx shadcn@latest add @manner/agent-rules\npnpm dlx shadcn@latest add @manner/button\n```\n\n## Definition of done\n\nA stable component has semantic tokens, light and dark modes, keyboard tests, accessible state, visible focus, reduced motion, mobile behavior, long-content coverage, relevant loading/error/empty states, documentation, and real usage in at least one application composition.\n"
